import hashlib,json,re,statistics
from pathlib import Path
ROOT=Path('<ROUND_ROOT>'); CAP=ROOT/'captures'
DEST=Path('<CHECKOUT>/docs/board/doing/codex_0160_validation/evidence')
INDEX={}
def clean(s):
 s=s.replace(str(ROOT),'<ROUND_ROOT>').replace('<CHECKOUT>','<CHECKOUT>').replace('<HOME>','<HOME>')
 s=re.sub(r'<TEMP>[A-Za-z0-9/_.+-]*','<TEMP>',s)
 s=re.sub(r'gAAAA[A-Za-z0-9_=-]{40,}','<OPAQUE_ENCRYPTED_AGENT_MESSAGE>',s)
 return s

def raw(p):
 p=Path(p); data=p.read_bytes(); INDEX[str(p.relative_to(ROOT))]=hashlib.sha256(data).hexdigest()
 return clean(data.decode(errors='replace'))
def j(p):return json.loads(raw(p))
def lines(p):
 if not p.exists():return []
 return [json.loads(x) for x in raw(p).splitlines() if x.strip()]
def write(name,obj):
 (DEST/name).write_text(clean(json.dumps(obj,indent=2,ensure_ascii=False))+'\n')
def selected(p,names):return {name:j(p/name) for name in names if (p/name).exists()}
def stream(p):
 result=[]
 if p.exists():
  for line in raw(p).splitlines():
   try: result.append(json.loads(line))
   except ValueError: pass
 return result

def native(thread):
 paths=list((ROOT/'codex-home').glob('sessions/*/*/*/*'+thread+'.jsonl'))
 assert len(paths)==1
 return stream(paths[0])

cases={}; builds={}; identities={}
for p in sorted(CAP.iterdir()):
 if not p.is_dir() or p.name=='sanitized':continue
 if (p/'command.json').exists():
  command=j(p/'command.json'); files=command.pop('harness_files',{})
  identity=command.pop('codex_identity',None)
  if identity:
   ident=hashlib.sha256(json.dumps(identity,sort_keys=True).encode()).hexdigest();identities[ident]=identity;command['codex_identity_ref']=ident
  key=hashlib.sha256(json.dumps(files,sort_keys=True).encode()).hexdigest()
  builds[key]=files; command['harness_snapshot']=key
  cases[p.name]={'command':command,**selected(p,['process-result.json','terminal-result.json'])}
write('harness-snapshots.json',builds)
write('provenance.json',{'identity':j(ROOT/'identity.json'),'quota_reservations':lines(ROOT/'turns.jsonl'),'harness_snapshots_file':'harness-snapshots.json','codex_identities':identities,'cases':cases})
base={}
for name in ('00-preflight','05-config-schema','10-headless-fire','60-exec-resume','61-rollout-identity','81-enrolled-coverage','84-fresh-project'):
 p=CAP/name
 base[name]={str(x.relative_to(p)):raw(x) for pattern in ('results/*.oracle.txt','results/verdict.txt','results/*findings.txt','results/*summary.txt','results/*matrix.txt','results/*.exit','results/*.last-message.txt','meta/version.txt') for x in sorted(p.glob(pattern))}
p=CAP/'88-b2-enrollment'
base['88-b2-enrollment']={'preflight':j(p/'results/preflight.json'),'enrollment':j(p/'results/enrollment.json'),'dispatcher':j(p/'results/forge-doctor.json')['hook_dispatcher'],'receipt':j(p/'96427-observation-receipt.json'),'launchers':lines(p/'hook-launchers.jsonl')}
notes=CAP/'80-enroll-fixture/meta/operator-notes.txt'
if notes.exists():base['operator_enrollment_notes']=raw(notes)
write('baseline.json',base)
product={}
for p in sorted(CAP.glob('8[9]-*'))+sorted(CAP.glob('91-*'))+sorted(CAP.glob('92-*')):
 if not p.is_dir() or 'failure' in p.name or 'missing-login' in p.name or 'env-' in p.name:continue
 product[p.name]={'stream':stream(p/'stdout'),'hooks':lines(p/'hook-launchers.jsonl'),'reviewer':lines(p/'reviewer.jsonl'),'usage':lines(p/'usage-correlation.jsonl'),'receipts':{x.name:j(x) for x in p.glob('*receipt.json')}}
project=CAP/'fixture/proj'
product['filesystem']={name:(project/name).exists() for name in ('src/blocked_b2.py','src/paired_b2.py','tests/test_paired_b2.py','src/absent_b2.py','updated_b2.txt','malformed_b2.txt','supervised_b2.txt','advisory_b2.txt','advisory_resume_b2.txt','producer_b2.txt','unmarked_b2.txt')}
write('product.json',product)
warning={}
oracles={x['name']:x['nonce'] for x in lines(CAP/'b2-results.jsonl')}
for p in sorted(CAP.glob('90-*')):
 warning[p.name]={'nonce':oracles[p.name],'last':raw(p/'last.txt'),'events':stream(p/'stdout'),'hook_payloads':[j(x) for x in p.glob('PreToolUse-*.stdin.json')]}
write('feedback.json',warning)
coverage={}
for name in ('93-tools-off','93-tools-on','93-mcp-positive'):
 p=CAP/name; events=stream(p/'stdout')
 tid=next(x['thread_id'] for x in events if x.get('type')=='thread.started')
 coverage[name]={'events':events,'payloads':[j(x) for x in p.glob('PreToolUse-*.stdin.json')], 'native_tool_records':[x for x in native(tid) if x.get('type')=='response_item' and x['payload'].get('type') in ('function_call','function_call_output','custom_tool_call','custom_tool_call_output')]}
coverage['mcp_requests']=lines(CAP/'mcp-positive-requests.jsonl')
coverage['timings']=lines(CAP/'93-dispatch-timings/samples.jsonl')
coverage['reviewers']=lines(CAP/'93-dispatch-timings/reviewer.jsonl')
coverage['cold_admission']=j(CAP/'93-cold-admission/samples.json')
coverage['cold_reviewers']=lines(CAP/'93-cold-admission/reviewer.jsonl')
write('dispatcher-timings.json',{key:coverage.pop(key) for key in ('timings','reviewers','cold_admission','cold_reviewers')})
coverage['dispatcher_timings_file']='dispatcher-timings.json'
write('coverage.json',coverage)
forks={}
for p in sorted(CAP.glob('94-*')):
 forks[p.name]={**selected(p,['fork-facts.json','concurrent-facts.json']),'last':raw(p/'last.txt') if (p/'last.txt').exists() else None,'fork_last':raw(p/'fork-last.txt') if (p/'fork-last.txt').exists() else None,'events':stream(p/'stdout'),'reviewer':lines(p/'reviewer.jsonl'),'hooks':lines(p/'hook-launchers.jsonl'),'payloads':[j(x) for x in p.glob('PreToolUse-*.stdin.json')]}
p=CAP/'94-parent-mutation'; a=j(p/'manifest-before.json');b=j(p/'manifest-after.json')
forks['parent_delta']={'old_confirmed_at':a['confirmed']['confirmed_at'],'new_confirmed_at':b['confirmed']['confirmed_at'],'appended_decisions':b['confirmed']['policy']['decisions'][len(a['confirmed']['policy']['decisions']):],'codex_before':a['confirmed'].get('codex'),'codex_after':b['confirmed'].get('codex')}
write('forks.json',forks)
setup=lines(CAP/'setup.jsonl'); statuses=[];activities=[]
for x in setup:
 if x['command'][1:4]==['policy','supervisor','status']:statuses.append(json.loads(x['stdout']))
 if x['command'][1:3]==['telemetry','activity']:activities.append(json.loads(x['stdout']))
lifetime={p.name:{'reviewer':lines(p/'reviewer.jsonl'),'events':stream(p/'stdout'),'hooks':lines(p/'hook-launchers.jsonl'),**selected(p,['process-result.json','injected-signal.json']),'file_exists':(project/(p.name+'.txt')).exists()} for p in sorted(CAP.glob('95-*'))}
write('lifetime-status.json',{'status_after_each_case':statuses,'activity_after_each_case':activities})
lifetime['status_file']='lifetime-status.json'
write('lifetime.json',lifetime)
background={}
for p in sorted(CAP.glob('96-*')):
 background[p.name]={'events':stream(p/'stdout'),'hooks':{x.name:j(x) for x in p.glob('Background-*.json')},**selected(p,['process-result.json'])}
for p in sorted(CAP.glob('97-tui-*')):
 if 'failure' in p.name:continue
 if not (p/'terminal.log').exists():continue
 s=raw(p/'terminal.log');s=re.sub(r'\x1b\][^\x07]*(?:\x07|\x1b\\)','',s);s=re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]|\x1b[\x20-\x7e]','',s)
 background[p.name]={'terminal_plain':s,**selected(p,['terminal-actions.json','terminal-result.json','active-refusal.json','process-result.json']),'hooks':{x.name:j(x) for x in p.glob('Background-*.json')},'stop':[j(x) for x in p.glob('Stop-*.stdin.json')],'receipts':{x.name:j(x) for x in p.glob('*receipt.json')}}
write('interactive-background.json',background)
stop_thread='01a11e50-142a-7850-a363-bc8ab9bb41fc'
stop_records=[x for x in native(stop_thread) if (x.get('type')=='event_msg' and x['payload'].get('type')!='token_count') or (x.get('type')=='response_item' and x['payload'].get('type')=='message')]
p=CAP/'81-enrolled-coverage'
stop={'thread':stop_thread,'native_records':stop_records,'hooks':[]}
for path in p.rglob('*.stdin.json'):
 payload=j(path)
 if payload.get('session_id')==stop_thread:stop['hooks'].append(payload)
write('stop.json',stop)
write('artifact.json',{'wheel':j(CAP/'wheel.json'),'preflight_after':j(CAP/'preflight-after.json'),'teardown':j(CAP/'teardown.json')})
(DEST/'environment.sh.txt').write_text('# Sanitized evidence template; placeholders require editing before use.\n'+raw(ROOT/'run'))
write('source-hashes.json',{'redaction':'Local paths replaced; opaque encrypted agent-message strings replaced, not decoded. Only synthetic probe conversations included. SHA256 hashes identify raw private sources before redaction.','sources':INDEX})
print('Exported',len(list(DEST.glob('*.json'))),'JSON evidence files')
